module vga_display(
    input wire clk,
    output reg hsync,
    output reg vsync,
    output reg [11:0] rgb
    );
    
    reg [1:0] count = 0;
    
    reg [9:0] hcount = 0;
    reg [9:0] vcount = 0;
    
    reg pclk;
    
    reg video_en = 0; 
        
    always @(posedge clk)
    begin
        if(count == 0)
        begin
            count <= count + 1;
            pclk <= 1;
        end
        else
        begin
            count <= count + 1;
            pclk <= 0;
        end
    end
    
    
    always @(posedge pclk)
    begin
        if(hcount == 799) hcount <= 0;
        else    hcount <= hcount + 1;
    end
    
    always @(posedge pclk)
    begin
        if(hcount == 799)
        begin
            if(vcount == 524) vcount <= 0;
            else vcount <= vcount + 1;
        end
    end
    
    always @(*)
    begin
    
        if(hcount <= 639 && vcount <= 479) video_en <= 1;
        else video_en <= 0;
    
        if((hcount >= 656) && (hcount <= 751)) hsync <= 1;
        else hsync <= 0;
        
        if((vcount >= 513) && (vcount <= 515)) vsync <= 1;
        else vsync <= 0;
        
    end
    
    reg [0:127] mem [0:63];
    
    always @(*)
    begin
        if(video_en)
        begin
            if((hcount <= 127) && (vcount <= 63))
            begin
                if(mem[vcount][hcount] == 1) rgb <= 12'b1111_1111_1111;
                else rgb <= 12'b0;
            end
            else rgb <= 12'b0;
        end
        else rgb <= 12'b0;
    end
    
    
  always @(*)
  begin
  mem[0][0] = 0 ; 
  mem[0][1] = 0 ; 
  mem[0][2] = 0 ; 
  mem[0][3] = 0 ; 
